const value = String($json.vacante ?? '').trim();
if (!value) throw new Error('BOT_TOOL_INVALID_INPUT: se requiere el id, codigo o nombre de la vacante');
if (value.length > 200) throw new Error('BOT_TOOL_INVALID_INPUT: valor de vacante demasiado largo');
return [{ json: { vacante: value } }];
